(()=>{'use strict';
 const root=document.getElementById('ap-support');if(!root)return;
 const options=root.querySelector('.ap-support-options'),active=root.querySelector('.ap-chat-active'),compose=root.querySelector('.ap-chat-compose'),input=compose?.querySelector('textarea'),log=root.querySelector('.ap-chat-messages');if(!options||!active||!input)return;
 const entry=document.createElement('button');entry.type='button';entry.className='ap-voice-menu';entry.innerHTML='<span aria-hidden="true">◉</span><span>Voice conversation<small>Speak your message and hear replies</small></span><span aria-hidden="true">→</span>';options.append(entry);
 const tools=document.createElement('section');tools.className='ap-voice-tools';tools.setAttribute('aria-label','Voice conversation');tools.hidden=true;
 tools.innerHTML='<div class="ap-voice-visual" aria-hidden="true"><div class="ap-voice-orb"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v3m-3 0h6"/></svg></div><div class="ap-voice-bars"><i></i><i></i><i></i><i></i><i></i></div></div><div class="ap-voice-heading">কথা বলুন, সহজভাবে।</div><select aria-label="Voice language"><option value="en-US">English</option><option value="bn-BD">বাংলা</option></select><button type="button" aria-pressed="false">Mic on</button><label><input type="checkbox">Read replies aloud</label><button type="button" class="ap-voice-exit">End voice chat</button><button type="button" class="ap-voice-transcript">View transcript</button><p class="ap-voice-note" role="status">Start a conversation first. Then speak, review the text and send.</p>';
 active.prepend(tools);
 tools.querySelector('.ap-voice-transcript').addEventListener('click',()=>{active.classList.toggle('ap-show-transcript');});
 let voice=false,recognition=null;const mic=tools.querySelector('button'),language=tools.querySelector('select'),read=tools.querySelector('input'),note=tools.querySelector('p');
 function state(value){tools.dataset.voiceState=value;}
 function stop(){state('idle');recognition?.abort();recognition=null;mic.textContent='Use microphone';mic.setAttribute('aria-pressed','false');window.speechSynthesis?.cancel();}
 entry.addEventListener('click',()=>{voice=true;active.classList.add('ap-voice-mode');root.querySelector('.ap-live-open').click();tools.hidden=false;read.checked=true;state('idle');note.textContent='Tap the microphone to speak. Review your words, then send.';});
 tools.querySelector('.ap-voice-exit').addEventListener('click',()=>{voice=false;active.classList.remove('ap-voice-mode','ap-show-transcript');tools.hidden=true;read.checked=false;stop();});
 mic.addEventListener('click',()=>{if(recognition){stop();return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){note.textContent='Voice input is unavailable in this browser. Try Chrome or type your message.';return;}if(input.disabled){note.textContent='This conversation is closed. Start a new conversation.';return;}
  window.speechSynthesis?.cancel();const r=new Recognition();recognition=r;r.lang=language.value;r.interimResults=false;
  r.onresult=e=>{const text=e.results[0]?.[0]?.transcript?.trim();if(text){input.value=[input.value.trim(),text].filter(Boolean).join(' ').slice(0,4000);input.dispatchEvent(new Event('input',{bubbles:true}));note.textContent='Review your words, then press Send.';}};
  r.onerror=()=>{state('idle');note.textContent='Microphone stopped or access was denied. Try again or type.';};r.onend=()=>{state('idle');recognition=null;mic.textContent='Use microphone';mic.setAttribute('aria-pressed','false');};
  r.onstart=()=>state('listening');
  try{r.start();mic.textContent='Mic off';mic.setAttribute('aria-pressed','true');note.textContent='Listening…';}catch{stop();note.textContent='Could not start microphone. You can type instead.';}
 });
 new MutationObserver(changes=>{if(!voice||!read.checked||document.hidden||root.querySelector('.ap-chat-window').hidden)return;for(const change of changes)for(const node of change.addedNodes){if(node.nodeType!==1||!node.matches('.ap-chat-message.incoming'))continue;const text=node.querySelector('p')?.textContent;if(!text||!window.speechSynthesis||!window.SpeechSynthesisUtterance)continue;const speech=new SpeechSynthesisUtterance(text);speech.lang=/[\u0980-\u09ff]/.test(text)?'bn-BD':language.value;speech.onstart=()=>{state('speaking');note.textContent='Aptee is speaking…';};speech.onend=speech.onerror=()=>{state('idle');note.textContent='Tap the microphone to continue.';};window.speechSynthesis.speak(speech);}}).observe(log,{childList:true});
 root.querySelector('.ap-chat-close')?.addEventListener('click',stop);read.addEventListener('change',()=>{if(!read.checked){window.speechSynthesis?.cancel();state('idle');}});window.addEventListener('pagehide',stop);
})();
